KG42.register("rules-cb0ac1338d948b54d6ce260a",{"id":"02-dlmp::v141-c-R001","paper":"02-dlmp","record":{"rule_id":"v141-c-R001","mechanism_id":"v141-a-M01","name":"Local market clearing","process_stage":"clearing","market_meaning":"The local DLMPs defined by (33) and (37) can be interpreted as equilibrium conditions for electric distribution-system market clearing. Scope: Electric distribution-system market clearing under the DLMP expressions (33) and (37). Condition: The conventional household demand non-negativity constraint (7) does not bind, as assumed in these DLMP expressions. Coordination through autonomous responses to posted DLMPs can implement the DSO's efficient local allocations under the stated conditions. Scope: Decentralized implementation of the DSO's efficient EV-charging and conventional-demand allocations within the electric distribution network. Condition: Conventional household demand non-negativity constraint (7) does not bind; EV aggregators act as price takers, and loads respond to posted DLMPs by maximizing individual net surplus. Local allocations must satisfy energy-balance, transmission, nondemand-node, generation-node and demand-node constraints, conventional household demand non-negativity, charging-energy limits and driving requirements. Demand-node energy imports equal conventional household demand plus EV demand for the corresponding node and time period. Scope: Local allocations in the DSO distribution-network optimization problem (1)-(9). Condition: EVs charge only at the location they belong to, as assumed in the demand-node balance model.","independence_rationale":"Relations governed by the approved function clearing.local under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.local","coordination.price_signal","pricing.local"],"E":[{"edge_id":"v141-c-R001-E001","source":"coordination.price_signal","target":"clearing.local","type":"links","constraint_ids":["v141-c-R001-C002"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E27","v141-b-g01-E35"]},{"edge_id":"v141-c-R001-E002","source":"pricing.local","target":"clearing.local","type":"links","constraint_ids":["v141-c-R001-C001"],"evidence_ids":["v141-b-g01-E25","v141-b-g01-E26"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Decentralized implementation of the DSO's efficient EV-charging and conventional-demand allocations within the electric distribution network. | Electric distribution-system market clearing under the DLMP expressions (33) and (37). | Local allocations in the DSO distribution-network optimization problem (1)-(9).","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E12","v141-b-g01-E13","v141-b-g01-E25","v141-b-g01-E26","v141-b-g01-E27","v141-b-g01-E35"]},"x":[{"variable_id":"v141-c-R001-x-001","symbol":"x_{i,t}","meaning":"EV charging energy at time period t at node i (EV demand at node i and time t).","kind":"operational","domain":"EV charging energy at demand node i and period t; constrained by 0 \u003c= x_{i,t} \u003c= E_{i,t} in (8).","unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E13","v141-b-g01-E29","v141-b-g01-E30"]},{"variable_id":"v141-c-R001-x-002","symbol":"c_{i,t}","meaning":"Conventional household demand at time period t at node i (elastic conventional demand).","kind":"operational","domain":"Elastic conventional household demand at node i and period t; constrained non-negative by (7): c_{i,t} >= 0.","unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E13"]},{"variable_id":"v141-c-R001-x-003","symbol":"r_{i,t}","meaning":"Net active power import/export at time period t at node i (positive for import).","kind":"operational","domain":"Net active power import/export at node i and period t; for demand nodes r_{i,t}=c_{i,t}+x_{i,t} by (6).","unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E10","v141-b-g01-E13"]}],"theta":[{"parameter_id":"v141-c-R001-theta-001","symbol":"E_{i,t}","meaning":"EV charging energy limit at time period t at node i.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E13"]},{"parameter_id":"v141-c-R001-theta-002","symbol":"S^-_{i,t}","meaning":"Minimum aggregate battery state of charge (SOC) at time period t at node i.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E13"]},{"parameter_id":"v141-c-R001-theta-003","symbol":"S^+_{i,t}","meaning":"Maximum aggregate battery state of charge (SOC) at time period t at node i.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E13"]},{"parameter_id":"v141-c-R001-theta-004","symbol":"S_{i,0}","meaning":"Initial aggregate battery state of charge (SOC) at node i.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E13"]},{"parameter_id":"v141-c-R001-theta-005","symbol":"d_{i,t}","meaning":"Driving energy requirement at time period t at node i.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E13"]},{"parameter_id":"v141-c-R001-theta-006","symbol":"P_{LMP,t}","meaning":"System locational marginal price (LMP) at time period t for the node feeding the distribution grid; a fixed reference price input to the local DLMP expressions.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-E20","v141-b-g01-E22"]},{"parameter_id":"v141-c-R001-theta-007","symbol":"D_{l,i}","meaning":"Power transfer distribution factor (PTDF) coefficient of line l with respect to a unit injection at node i.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["l","i"],"evidence_ids":["v141-b-g01-E10","v141-b-g01-E22"]}],"phi":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"The local DLMPs defined by (33) and (37) can be interpreted as equilibrium conditions for electric distribution-system market clearing. Scope: Electric distribution-system market clearing under the DLMP expressions (33) and (37). Condition: The conventional household demand non-negativity constraint (7) does not bind, as assumed in these DLMP expressions.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E25","v141-b-g01-E26"]},{"constraint_id":"v141-c-R001-C002","kind":"procedural","role":"core","statement":"Coordination through autonomous responses to posted DLMPs can implement the DSO's efficient local allocations under the stated conditions. Scope: Decentralized implementation of the DSO's efficient EV-charging and conventional-demand allocations within the electric distribution network. Condition: Conventional household demand non-negativity constraint (7) does not bind; EV aggregators act as price takers, and loads respond to posted DLMPs by maximizing individual net surplus.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E27","v141-b-g01-E35"]},{"constraint_id":"v141-c-R001-C003","kind":"procedural","role":"core","statement":"Local allocations must satisfy energy-balance, transmission, nondemand-node, generation-node and demand-node constraints, conventional household demand non-negativity, charging-energy limits and driving requirements. Demand-node energy imports equal conventional household demand plus EV demand for the corresponding node and time period. Scope: Local allocations in the DSO distribution-network optimization problem (1)-(9). Condition: EVs charge only at the location they belong to, as assumed in the demand-node balance model.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E12","v141-b-g01-E13"]},{"constraint_id":"v141-c-R001-C004","kind":"mathematical","role":"supporting","statement":"Source equation (33): under the condition that the conventional household demand non-negativity constraint (7) does not bind (so xi_{i,t}=0), the DLMP at node i and time t equals the system LMP plus the locational congestion markup varphi_{i,t}, which is the PTDF-weighted sum of line-flow dual differences.","expression":"P_{DLMP,i,t} = P_{LMP,t} + \\varphi_{i,t}, \\quad \\varphi_{i,t} = \\sum_{l \\in L} (\\lambda^+_{l,t} - \\lambda^-_{l,t}) D_{l,i}, \\quad \\xi_{i,t} = 0 \\text{ assuming (7) does not bind.}","formalization_origin":"source","template_id":null,"members":["pricing.local","clearing.local"],"variable_refs":[],"parameter_refs":["v141-c-R001-theta-006","v141-c-R001-theta-007"],"evidence_ids":["v141-b-g01-E22"]},{"constraint_id":"v141-c-R001-C005","kind":"mathematical","role":"supporting","statement":"Source equation (37): the DLMP at node i and time t can be written as a linear combination of the dual variables of the EV constraints, with one expression for nonterminal periods t in T\\{|T|} and a two-term expression for the terminal period t=|T|; xi_{i,t}=0 assuming constraint (7) does not bind.","expression":"P_{DLMP,i,t} = \\begin{cases} -\\mu^+_{i,t} + \\mu^-_{i,t} - \\sum_{t' \\ge t+1} \\kappa^+_{i,t'} + \\sum_{t' \\ge t+1} \\kappa^-_{i,t'}, & \\forall i \\in N_c, \\forall t \\in T \\backslash \\{|T|\\} \\\\ -\\mu^+_{i,t} + \\mu^-_{i,t}, & \\forall i \\in N_c, \\forall t = \\{ |T| \\} \\end{cases} \\text{ where } \\xi_{i,t} = 0 \\text{ assuming (7) does not bind.}","formalization_origin":"source","template_id":null,"members":["pricing.local","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E25"]},{"constraint_id":"v141-c-R001-C006","kind":"mathematical","role":"supporting","statement":"Source equation (6): for demand nodes, the net active power import equals the sum of conventional household demand and EV demand at the corresponding node and time period.","expression":"r_{i,t} = c_{i,t} + x_{i,t}, \\quad \\forall i \\in N_c, \\forall t \\in T.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R001-x-001","v141-c-R001-x-002","v141-c-R001-x-003"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E10","v141-b-g01-E13"]},{"constraint_id":"v141-c-R001-C007","kind":"mathematical","role":"supporting","statement":"Source equation (2): total power-flow balance requires the sum of net active power imports over all nodes to be zero in each time period.","expression":"\\sum_{i \\in N} r_{i,t} = 0, \\quad \\forall t \\in T.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R001-x-003"],"parameter_refs":[],"evidence_ids":["v141-b-g01-E10"]},{"constraint_id":"v141-c-R001-C008","kind":"mathematical","role":"supporting","statement":"Source equation (8): EV charging energy is bounded between zero and the charging energy limit at each demand node and time period.","expression":"0 \\le x_{i,t} \\le E_{i,t}, \\quad \\forall i \\in N_c, \\forall t \\in T.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R001-x-001"],"parameter_refs":["v141-c-R001-theta-001"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E13"]},{"constraint_id":"v141-c-R001-C009","kind":"mathematical","role":"supporting","statement":"Source equation (9): aggregate battery SOC equals the initial SOC plus cumulative charging energy up to t-1 minus cumulative driving energy requirement up to t, and is bounded by the minimum and maximum SOC bounds for all demand nodes and all periods except the first.","expression":"S^-_{i,t} \\le S_{i,0} + \\sum_{t' \\le t-1} x_{i,t'} - \\sum_{t' \\le t} d_{i,t'} \\le S^+_{i,t}, \\quad \\forall i \\in N_c, \\forall t \\in T \\backslash \\{1\\}.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R001-x-001"],"parameter_refs":["v141-c-R001-theta-002","v141-c-R001-theta-003","v141-c-R001-theta-004","v141-c-R001-theta-005"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E13"]}],"pi":[{"evidence_id":"v141-b-g01-E02","location":{"location_id":"src-16569f9a14-p01-c1r2__v141-a-M01-participation","page":1,"printed_page":"203","section":"Abstract","anchor_text":"Abstract This paper presents an integrated distribution lo cational marginal pricing (DLMP) method d","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"unknown"},"source_text":"It is also shown that the socially optimal charging schedule can be implemented through a decentralized mechanism where loads respond autonomously to the posted DLMPs by maximizing their individual net surplus."},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-16569f9a14-p03-c1r2__v141-a-M01-clearing","page":3,"printed_page":"205","section":"II. Determination of DLMPs Using Integrated Optimization","anchor_text":"( ) (7) is (8) an th fo (9) The DSO objective is to maximize the social surplus in (1) subject to th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"unknown"},"source_text":"The DSO objective is to maximize the social surplus in (1) subject to the energy-balance constraints in (2), the transmission constraints in (3), the nondemand node constraints in (4), generation node balance constraints in (5), the demand node balance constraints in (6), the conventional household demand non-negativity constraints in (7), the charging energy limit constraints in (8), and the driving requirement constraints in (9)."},{"evidence_id":"v141-b-g01-E13","location":{"location_id":"src-16569f9a14-p03-c1r3__v141-a-M01-clearing","page":3,"printed_page":"205","section":"II. Determination of DLMPs Using Integrated Optimization","anchor_text":"to, which requires that the energy import is the sum of the conventional household demand and EV dem","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"unknown"},"source_text":"For the demand node balance constraints in (6), the assumption is that EVs only charge energy at the location they belong to, which requires that the energy import r_{i,t} is the sum of the conventional household demand c_{i,t} and EV demand x_{i,t} at time period t at node i. The elastic conventional household demand c_{i,t} is constrained to be non-negative in (7). The EV demand x_{i,t} is constrained between 0 and charging energy limit E_{i,t} at time period t at node i in (8). E_{i,t} varies over time to reflect the availability of EVs across hours. The SOC of EV batteries at time period t at node i is the sum of its initial SOC and total charging energy x_{i,t} up to time period t-1 minus the total driving energy requirement d_{i,t} up to time period t. The SOC is constrained between minimum SOC S^-_{i,t} and maximum SOC S^+_{i,t} in (9). The variables in parentheses next to each constraint denote the Lagrange multipliers corresponding to that constraint."},{"evidence_id":"v141-b-g01-E25","location":{"location_id":"src-16569f9a14-p04-c2r2__v141-a-M01-pricing","page":4,"printed_page":"206","section":"II. Determination of DLMPs Using Integrated Optimization","anchor_text":"29) DF) (37) be on where assuming (7) does not bind. The DLMPs deﬁned by (33) and (37) can be interp","equation_id":"(37)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"(37) \\;\\;\\;\\;\\;\\;\\;\\;\\;\\; = \\begin{cases} -\\mu^+_{i,t} + \\mu^-_{i,t} - \\sum_{t' \\ge t+1} \\kappa^+_{i,t'} + \\sum_{t' \\ge t+1} \\kappa^-_{i,t'} & \\forall i \\in N_c, \\forall t \\in T \\backslash \\{|T|\\} \\\\ -\\mu^+_{i,t} + \\mu^-_{i,t} & \\forall i \\in N_c, \\forall t = \\{ |T| \\} \\end{cases}\nwhere \\xi_{i,t} = 0 assuming (7) does not bind."},{"evidence_id":"v141-b-g01-E26","location":{"location_id":"src-16569f9a14-p04-c2r2__v141-a-M01-pricing","page":4,"printed_page":"206","section":"II. Determination of DLMPs Using Integrated Optimization","anchor_text":"29) DF) (37) be on where assuming (7) does not bind. The DLMPs deﬁned by (33) and (37) can be interp","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"unknown"},"source_text":"The DLMPs defined by (33) and (37) can be interpreted as the equilibrium conditions for the electric distribution system market clearing. The market dynamics and the economic behavior of market participants under the DLMPs are discussed in Section IV."},{"evidence_id":"v141-b-g01-E27","location":{"location_id":"src-16569f9a14-p04-c2r3__v141-a-M01-participation","page":4,"printed_page":"206","section":"III. Aggregator-Based Optimal EV Charging Management","anchor_text":") charging management controlled by individual EV users, ag- 32) gregator-based charging management ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The EV charging management can take different forms: charging management controlled by individual EV users, aggregator-based charging management and proper mixture of the two mechanisms. In this paper, the aggregator-based EV charging management implementation is used. In the aggregator-based EV charging management concept, the EV aggregator is a profit-seeking entity who takes care of the EV fleet on behalf of the EV users, ensures that the energy needs are satisfied, and provides customized service and charging solution. The objective of EV aggregators is to meet the energy needs of EV users with the minimum charging cost. It is also assumed that each EV aggregator only controls a small portion of the EVs so that EV aggregators do not have market power and act as price takers in the DSO market."},{"evidence_id":"v141-b-g01-E35","location":{"location_id":"src-16569f9a14-p05-c1r4__v141-a-M01-validation","page":5,"printed_page":"207","section":"III. Aggregator-Based Optimal EV Charging Management","anchor_text":"S DL ha This implies that (43) and (44) hold under the optimal on solution . Equations (41), (42), a","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Corollary 1: The efficient allocation of the DSO problem {x^*_{i,t}, c^*_{i,t}} can be achieved in a decentralized system under the DLMPs, if the non-negativity constraint of conventional household demand (7) does not bind."},{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-16569f9a14-p03-c1r1__v141-a-M01-clearing","page":3,"printed_page":"205","section":"II. Determination of DLMPs Using Integrated Optimization","anchor_text":"LI et al.: DISTRIBUTION LOCATIONAL MARGINAL PRICING FOR OPTIMAL EV CHARG (2) (3) wh (4) (5) (6) (7) ","equation_id":"(2)-(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"(2) \\sum_{i \\in N} r_{i,t} = 0 \\;\\; \\forall t \\in T \\;\\; (p_t)\n(3) -K_l \\le \\sum_{i \\in N} D_{l,i}\\, r_{i,t} \\le K_l \\;\\; \\forall l \\in L, \\forall t \\in T \\;\\; (\\lambda^-_{l,t}, \\lambda^+_{l,t})\n(4) r_{i,t} = 0 \\;\\; \\forall i \\in N_n, \\forall t \\in T \\;\\; (\\omega_{i,t})\n(5) r_{g,t} + q_{g,t} = 0 \\;\\; \\forall t \\in T \\;\\; (\\omega_{g,t})\n(6) r_{i,t} = c_{i,t} + x_{i,t} \\;\\; \\forall i \\in N_c, \\forall t \\in T \\;\\; (\\rho_{i,t})"},{"evidence_id":"v141-b-g01-E11","location":{"location_id":"src-16569f9a14-p03-c1r2__v141-a-M01-clearing","page":3,"printed_page":"205","section":"II. Determination of DLMPs Using Integrated Optimization","anchor_text":"( ) (7) is (8) an th fo (9) The DSO objective is to maximize the social surplus in (1) subject to th","equation_id":"(7)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"(7) c_{i,t} \\ge 0 \\;\\; \\forall i \\in N_c, \\forall t \\in T \\;\\; (\\xi_{i,t})\n(8) 0 \\le x_{i,t} \\le E_{i,t} \\;\\; \\forall i \\in N_c, \\forall t \\in T \\;\\; (\\mu^-_{i,t}, \\mu^+_{i,t})\n(9) S^-_{i,t} \\le S_{i,0} + \\sum_{t' \\le t-1} x_{i,t'} - \\sum_{t' \\le t} d_{i,t'} \\le S^+_{i,t} \\;\\; \\forall i \\in N_c, \\forall t \\in T \\backslash \\{1\\} \\;\\; (\\kappa^-_{i,t}, \\kappa^+_{i,t})."},{"evidence_id":"v141-b-g01-E20","location":{"location_id":"src-16569f9a14-p04-c1r2__v141-a-M01-pricing","page":4,"printed_page":"206","section":"II. Determination of DLMPs Using Integrated Optimization","anchor_text":"(29) In the RBTS, the power transfer distribution factor (PTDF) coefﬁcient associated with the gener","equation_id":"(30)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"In the RBTS, the power transfer distribution factor (PTDF) coefficient associated with the generation node D_{l,g} is set to be 0 to enable unlimited import from the grid to the distribution network, which simplifies (29) and yields\n\\rho_{i,t} = P_{LMP,t} + \\sum_{l \\in L}(\\lambda^+_{l,t} - \\lambda^-_{l,t}) D_{l,i}   (30)"},{"evidence_id":"v141-b-g01-E22","location":{"location_id":"src-16569f9a14-p04-c1r3__v141-a-M01-pricing","page":4,"printed_page":"206","section":"II. Determination of DLMPs Using Integrated Optimization","anchor_text":"( ) ch (32) gr th ch The non-negativity constraint (7) can be excluded by implic- itly assuming an i","equation_id":"(33)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The non-negativity constraint (7) can be excluded by implicitly assuming an interior solution with respect to these constraints, forcing the dual variable associated with the constraint \\xi_{i,t} = 0. This can be explained as: every conventional household consumes at least a small positive amount of energy. Under this assumption, the DLMPs become\nP_{DLMP,i,t} = P_{LMP,t} + \\varphi_{i,t}   (33)\nwhere \\varphi_{i,t} = \\sum_{l \\in L}(\\lambda^+_{l,t} - \\lambda^-_{l,t}) D_{l,i}. The DLMPs can be interpreted as the sum of the reference price P_{LMP,t} and the locational congestion markup \\varphi_{i,t}, which is analogous to the marginal cost of congestion in the LMPs."},{"evidence_id":"v141-b-g01-E29","location":{"location_id":"src-16569f9a14-p04-c2r4__v141-a-M01-coordination","page":4,"printed_page":"206","section":"III. Aggregator-Based Optimal EV Charging Management","anchor_text":"an- (38) is- EV ng (39) (40) 34) The constraints in (39) and (40) are to ensure that the EV charging","equation_id":"(39)-(40)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"(39) 0 \\le x_{i,t} \\le E_{i,t} \\;\\; \\forall t \\in T \\;\\; (\\mu^-_{i,t}, \\mu^+_{i,t})\n(40) S^-_{i,t} \\le S_{i,0} + \\sum_{t' \\le t-1} x_{i,t'} - \\sum_{t' \\le t} d_{i,t'} \\le S^+_{i,t} \\;\\; \\forall t \\in T \\backslash \\{1\\} \\;\\; (\\kappa^-_{i,t}, \\kappa^+_{i,t}).\nThe constraints in (39) and (40) are to ensure that the EV charging energy and the EV battery SOC are within the specified limits."},{"evidence_id":"v141-b-g01-E30","location":{"location_id":"src-16569f9a14-p04-c2r4__v141-a-M01-coordination","page":4,"printed_page":"206","section":"III. Aggregator-Based Optimal EV Charging Management","anchor_text":"an- (38) is- EV ng (39) (40) 34) The constraints in (39) and (40) are to ensure that the EV charging","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"unknown"},"source_text":"When the DLMPs, P_{DLMP,i,t}, are known to the EV aggregator, the optimization problem is a linear programming problem and the EV aggregator optimally decides x_{i,t}, the amount of energy to purchase in each hour, to minimize the charging cost subject to the charging power limit constraints and the driving requirement constraints."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-validation"],"extras":{"decision_anchor":"clearing.local","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E26","quote":"The DLMPs defined by (33) and (37) can be interpreted as the equilibrium conditions for the electric distribution system market clearing."},{"evidence_id":"v141-b-g01-E25","quote":"where \\xi_{i,t} = 0 assuming (7) does not bind."}],[{"evidence_id":"v141-b-g01-E02","quote":"It is also shown that the socially optimal charging schedule can be implemented through a decentralized mechanism where loads respond autonomously to the posted DLMPs by maximizing their individual net surplus."},{"evidence_id":"v141-b-g01-E35","quote":"Corollary 1: The efficient allocation of the DSO problem {x^*_{i,t}, c^*_{i,t}} can be achieved in a decentralized system under the DLMPs, if the non-negativity constraint of conventional household demand (7) does not bind."},{"evidence_id":"v141-b-g01-E27","quote":"It is also assumed that each EV aggregator only controls a small portion of the EVs so that EV aggregators do not have market power and act as price takers in the DSO market."}],[{"evidence_id":"v141-b-g01-E12","quote":"The DSO objective is to maximize the social surplus in (1) subject to the energy-balance constraints in (2), the transmission constraints in (3), the nondemand node constraints in (4), generation node balance constraints in (5), the demand node balance constraints in (6), the conventional household demand non-negativity constraints in (7), the charging energy limit constraints in (8), and the driving requirement constraints in (9)."},{"evidence_id":"v141-b-g01-E13","quote":"For the demand node balance constraints in (6), the assumption is that EVs only charge energy at the location they belong to, which requires that the energy import r_{i,t} is the sum of the conventional household demand c_{i,t} and EV demand x_{i,t} at time period t at node i."}]],"C2_formalization":{"graph_sha256":"ae19c32b620a63c0c0ff42dba9c05afe46333569083854ffac00c9b24042d783","applicability":"formalized","reason":"The original procedural C001-C003 are retained unchanged. Source-supported mathematics for the local market-clearing DLMP definitions and local feasibility constraints is added: the DLMP decomposition (33) and its dual-variable form (37), the demand-node balance (6), aggregate energy balance (2), charging-energy bounds (8), and SOC/driving bounds (9). Variables r_{i,t}, c_{i,t}, x_{i,t} and fixed EV/network/price parameters are declared. Dual variables and the DLMP price itself cannot be classified as x or theta under the supplied schema; they remain symbolic in the transcribed expressions. All attached B evidence is unreviewed candidate support per the experiment policy, not independently verified source review.","bindings":[{"object_id":"v141-c-R001-x-001","node_ids":["clearing.local"],"edge_ids":[],"rationale":"EV charging energy x_{i,t} is an operational clearing variable at distribution demand nodes."},{"object_id":"v141-c-R001-x-002","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Conventional household demand c_{i,t} is an operational demand variable in the clearing problem."},{"object_id":"v141-c-R001-x-003","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Net active power import r_{i,t} is the node-level clearing balance variable."},{"object_id":"v141-c-R001-theta-001","node_ids":["clearing.local"],"edge_ids":[],"rationale":"EV charging energy limit E_{i,t} is a fixed input to the clearing constraints."},{"object_id":"v141-c-R001-theta-002","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Minimum SOC bound S^-_{i,t} is a fixed input to the clearing constraints."},{"object_id":"v141-c-R001-theta-003","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Maximum SOC bound S^+_{i,t} is a fixed input to the clearing constraints."},{"object_id":"v141-c-R001-theta-004","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Initial SOC S_{i,0} is a fixed input to the clearing constraints."},{"object_id":"v141-c-R001-theta-005","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Driving energy requirement d_{i,t} is a fixed input to the clearing constraints."},{"object_id":"v141-c-R001-theta-006","node_ids":["pricing.local","clearing.local"],"edge_ids":["v141-c-R001-E002"],"rationale":"System LMP P_{LMP,t} is a fixed reference price input to local DLMP clearing."},{"object_id":"v141-c-R001-theta-007","node_ids":["clearing.local"],"edge_ids":[],"rationale":"PTDF coefficient D_{l,i} is a fixed network parameter of the clearing problem."},{"object_id":"v141-c-R001-C001","node_ids":["pricing.local","clearing.local"],"edge_ids":["v141-c-R001-E002"],"rationale":"Original procedural equilibrium interpretation links local pricing and clearing."},{"object_id":"v141-c-R001-C002","node_ids":["coordination.price_signal","clearing.local"],"edge_ids":["v141-c-R001-E001"],"rationale":"Original procedural decentralized-response constraint links price-signal coordination to clearing."},{"object_id":"v141-c-R001-C003","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Original procedural local-allocation feasibility constraint."},{"object_id":"v141-c-R001-C004","node_ids":["pricing.local","clearing.local"],"edge_ids":["v141-c-R001-E002"],"rationale":"Formalized DLMP decomposition (33) links local pricing to clearing under the nonbinding condition."},{"object_id":"v141-c-R001-C005","node_ids":["pricing.local","clearing.local"],"edge_ids":["v141-c-R001-E002"],"rationale":"Formalized dual-variable DLMP expression (37) links local pricing to clearing."},{"object_id":"v141-c-R001-C006","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Demand-node balance is a local clearing constraint."},{"object_id":"v141-c-R001-C007","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Aggregate energy balance is the local clearing feasibility condition."},{"object_id":"v141-c-R001-C008","node_ids":["clearing.local"],"edge_ids":[],"rationale":"Charging-energy bounds are local clearing feasibility constraints."},{"object_id":"v141-c-R001-C009","node_ids":["clearing.local"],"edge_ids":[],"rationale":"SOC and driving-energy bounds are local clearing feasibility constraints."}],"revision_requests":["Consider adding explicit equilibrium-quantity nodes or object types for P_{DLMP,i,t}, line-flow duals lambda^+_{l,t}/lambda^-_{l,t}, EV duals mu^+/mu^- and kappa^+/kappa^-, and demand dual xi_{i,t}; the current x/theta split cannot classify these endogenous prices and multipliers.","Confirm whether the DLMP price P_{DLMP,i,t} should be represented as an equilibrium price object rather than as a variable or parameter.","If this rule is intended to include the decentralized aggregator-response equilibrium, expose the aggregator optimization members or confirm that R001 remains limited to the DSO clearing DLMP definitions."]}},"quarantined_references":[]}});
